(function(){'use strict';
function ready(fn){if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',fn,{once:true});else fn();}
ready(function(){
 var zone=document.querySelector('#home-historical-cases'); if(!zone||zone.dataset.archiveV2==='true')return; zone.dataset.archiveV2='true';
 var grid=zone.querySelector('.home-historical-grid'); if(!grid)return;
 var cards=Array.prototype.slice.call(grid.querySelectorAll('.home-historical-card'));
 var groups=[
  {key:'taiwan',label:'台灣',sub:'TAIWAN',match:function(c){return c.getAttribute('href').indexOf('/taiwan/')>-1;}},
  {key:'mainland',label:'中國大陸',sub:'MAINLAND CHINA',match:function(c){return c.getAttribute('href').indexOf('/mainland-china/')>-1;}},
  {key:'japan',label:'日本',sub:'JAPAN',match:function(c){return c.getAttribute('href').indexOf('/japan/')>-1;}}
 ];
 var head=zone.querySelector('.home-crafted-head'); if(head){var p=head.querySelector('p');if(p)p.textContent='依地區與年代展開案件檔案。先看見一個地方，再走進一段不能被時間帶走的記憶。';}
 var shell=document.createElement('div'); shell.className='history-archive-v2';
 var intro=document.createElement('div'); intro.className='history-map-panel'; intro.innerHTML='<div class="history-map-copy"><small>MEMORY MAP · CASE ARCHIVE</small><strong>那些不該被時間帶走的名字</strong><span>選擇地區，展開案件重點與閱讀入口</span></div><div class="history-map-art" aria-hidden="true"><i class="map-dot dot-tw">台灣</i><i class="map-dot dot-cn">大陸</i><i class="map-dot dot-jp">日本</i><b>東亞案件<br>記憶地圖</b></div>';
 shell.appendChild(intro);
 var accordion=document.createElement('div'); accordion.className='history-region-list';
 groups.forEach(function(g,idx){var mine=cards.filter(g.match);if(!mine.length)return;var details=document.createElement('details');details.className='history-region';details.dataset.region=g.key;if(idx===0)details.open=true;var summary=document.createElement('summary');summary.innerHTML='<span><small>'+g.sub+'</small><strong>'+g.label+'</strong></span><em>'+mine.length+' 件案件</em><b aria-hidden="true">＋</b>';details.appendChild(summary);var panel=document.createElement('div');panel.className='history-region-panel';mine.forEach(function(c){panel.appendChild(c);});details.appendChild(panel);accordion.appendChild(details);details.addEventListener('toggle',function(){if(details.open){Array.prototype.forEach.call(accordion.querySelectorAll('details'),function(other){if(other!==details)other.open=false;});if(window.gsap&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){window.gsap.fromTo(panel.querySelectorAll('.home-historical-card'),{y:18,opacity:0},{y:0,opacity:1,duration:.48,stagger:.07,ease:'power2.out',clearProps:'transform,opacity'});}}});});
 shell.appendChild(accordion); grid.replaceWith(shell);
 var foot=zone.querySelector('.home-historical-foot');if(foot)foot.innerHTML='<span>紙上留下案件，陶土留下記憶；制度必須留下改變。</span><span class="home-historical-note">地區索引 · 年代閱讀 · 重點式展開</span>';
 var style=document.createElement('style');style.id='history-archive-v2-style';style.textContent=`
.history-archive-v2{display:grid;grid-template-columns:minmax(260px,.72fr) minmax(0,1.28fr);gap:24px;align-items:start;margin-top:24px}.history-map-panel{position:sticky;top:92px;min-height:390px;border:1px solid rgba(78,86,79,.15);border-radius:30px;padding:26px;background:linear-gradient(145deg,rgba(247,242,232,.96),rgba(225,235,229,.88));box-shadow:0 18px 46px rgba(55,64,59,.09);overflow:hidden}.history-map-copy small{display:block;color:#846554;font-weight:900;letter-spacing:.12em;font-size:.68rem}.history-map-copy strong{display:block;margin-top:8px;color:#3f4944;font-size:clamp(1.35rem,2.3vw,2rem);line-height:1.25}.history-map-copy span{display:block;margin-top:8px;color:#68726d;line-height:1.6}.history-map-art{position:relative;height:235px;margin-top:20px;border-radius:48% 52% 45% 55%/54% 43% 57% 46%;background:radial-gradient(circle at 58% 44%,rgba(153,181,168,.5),transparent 7%),linear-gradient(145deg,rgba(191,207,196,.42),rgba(239,221,211,.38));border:1px dashed rgba(88,110,99,.25)}.history-map-art:before,.history-map-art:after{content:'';position:absolute;border-radius:50%;background:rgba(255,255,255,.42)}.history-map-art:before{width:130px;height:90px;left:18%;top:25%;transform:rotate(-18deg)}.history-map-art:after{width:95px;height:125px;right:17%;top:18%;transform:rotate(20deg)}.history-map-art>b{position:absolute;left:50%;top:50%;z-index:2;transform:translate(-50%,-50%);color:#53665d;text-align:center;font-size:1rem;line-height:1.45}.map-dot{position:absolute;z-index:3;padding:6px 9px;border-radius:999px;background:#fff9f4;color:#765446;font-size:.72rem;font-style:normal;font-weight:900;box-shadow:0 5px 16px rgba(65,71,66,.12)}.dot-cn{left:29%;top:31%}.dot-tw{left:48%;top:62%}.dot-jp{right:15%;top:30%}.history-region-list{display:grid;gap:13px}.history-region{border:1px solid rgba(80,86,81,.14);border-radius:22px;background:rgba(255,253,249,.82);box-shadow:0 10px 28px rgba(64,62,56,.06);overflow:hidden}.history-region summary{list-style:none;display:grid;grid-template-columns:1fr auto auto;gap:14px;align-items:center;padding:18px 20px;cursor:pointer;color:#414b46}.history-region summary::-webkit-details-marker{display:none}.history-region summary small{display:block;color:#9a7562;font-size:.65rem;font-weight:900;letter-spacing:.11em}.history-region summary strong{display:block;margin-top:2px;font-size:1.15rem}.history-region summary em{font-style:normal;color:#7b746d;font-size:.8rem}.history-region summary>b{display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:#e7eee9;color:#53675d;font-size:1.15rem;transition:transform .25s ease}.history-region[open] summary>b{transform:rotate(45deg)}.history-region-panel{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;padding:0 16px 18px}.history-region-panel .home-historical-card{margin:0!important;min-width:0!important;width:auto!important;height:auto}.history-region-panel .home-historical-card:last-child:nth-child(odd){grid-column:1/-1}.home-guest-message-section{padding-top:10px!important;padding-bottom:10px!important}.home-guest-message-details>summary{min-height:auto}.home-protection-wall{padding-top:20px!important}.home-protection-wall-card{max-width:1180px;margin-inline:auto}.home-activity-records-standalone{padding-top:42px!important}@media(max-width:820px){.history-archive-v2{grid-template-columns:1fr;gap:14px}.history-map-panel{position:relative;top:auto;min-height:0;padding:20px;border-radius:24px}.history-map-art{height:155px}.history-region-panel{grid-template-columns:1fr;padding:0 12px 14px}.history-region-panel .home-historical-card:last-child:nth-child(odd){grid-column:auto}.history-region summary{padding:16px}.history-map-copy strong{font-size:1.35rem}.home-guest-message-section{padding-block:6px!important}}
`;document.head.appendChild(style);
 if(window.gsap&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){window.gsap.fromTo(intro,{y:24,opacity:0},{y:0,opacity:1,duration:.7,ease:'power3.out',scrollTrigger:{trigger:zone,start:'top 82%',once:true}});window.gsap.fromTo(accordion.children,{y:20,opacity:0},{y:0,opacity:1,duration:.55,stagger:.09,ease:'power2.out',scrollTrigger:{trigger:accordion,start:'top 88%',once:true}});}
});
})();